class RowPattern {
    void printPattern() {
        for (int column = 1; column <= 5; column++) {
            System.out.print("* ");
        }
        System.out.println("_");
    }
}
public class Main {
    public static void main(String[] args) {
        RowPattern pattern = new RowPattern();
        pattern.printPattern();
    }
}

