class IncreasingNumberPattern {
    void printPattern() {
        for (int row = 1; row <= 5; row++) {
            for (int number = 1; number <= row; number++) {
                if (number > 1) {
                    System.out.print(" ");
                }
                System.out.print(number);
            }
            System.out.println();
        }
    }
}
public class Main {
    public static void main(String[] args) {
        IncreasingNumberPattern pattern =
          new IncreasingNumberPattern();
        pattern.printPattern();
    }
}

class DecreasingNumberPattern {
    void printPattern() {
        for (int row = 5; row >= 1; row--) {
            for (int number = 1; number <= row; number++) {
                if (number > 1) {
                    System.out.print(" ");
                }
                System.out.print(number);
            }
            System.out.println();
        }
    }
}
public class Main {
    public static void main(String[] args) {
        DecreasingNumberPattern pattern =
                new DecreasingNumberPattern();
        pattern.printPattern();
    }
}

