class IncreasingValuePattern {
    void printPattern() {
        for (int row = 1; row <= 5; row++) {
            int repetitions = 6 - row;
            for (int column = 1; column <= repetitions; column++) {
                if (column > 1) {
                    System.out.print(" ");
                }
                System.out.print(row);
            }
            System.out.println();
        }
    }
}
public class Main {
