class SymbolRectanglePattern {
    void printPattern() {
        for (int row = 1; row <= 5; row++) {
            for (int column = 1; column <= 5; column++) {
                System.out.print("_ ");
            }
            for (int column = 1; column <= 5; column++) {
                System.out.print("*");

                if (column < 5) {
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }
}
public class Main {
    public static void main(String[] args) {
        SymbolRectanglePattern pattern =
                new SymbolRectanglePattern();
        pattern.printPattern();
    }
}

class IncreasingUnderscorePattern {
    void printPattern() {
        for (int row = 1; row <= 5; row++) {
            for (int underscore = 1; underscore <= row; underscore++) {
                System.out.print("_ ");
            }
            for (int star = 1; star <= 5; star++) {
                System.out.print("*");
                if (star < 5) {
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }
}
public class Main {
    public static void main(String[] args) {
        IncreasingUnderscorePattern pattern =
                new IncreasingUnderscorePattern();
        pattern.printPattern();
    }
}

class DecreasingStarPattern {
    void printPattern() {
        for (int row = 1; row <= 5; row++) {
            for (int underscore = 1; underscore <= 5; underscore++) {
                System.out.print("_ ");
            }
            int numberOfStars = 6 - row;
            for (int star = 1; star <= numberOfStars; star++) {
                System.out.print("*");
                if (star < numberOfStars) {
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }
}
public class Main {
    public static void main(String[] args) {
        DecreasingStarPattern pattern =
                new DecreasingStarPattern();
        pattern.printPattern();
    }
}

